// Package store persists Resource Manager entities in the `rm` database
// (REQ-PLT-080): fixed queries are generated by sqlc (sqlcdb), List queries
// with filters and keyset paging are built here.
package store

import (
	"context"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/mindevis/qstack/internal/resourcemanager/domain"
	"github.com/mindevis/qstack/internal/resourcemanager/store/sqlcdb"
	"github.com/mindevis/qstack/pkg/db"
)

//go:embed migrations/*.sql
var migrations embed.FS

// Migrations returns the service's migrations.
func Migrations() fs.FS {
	sub, err := fs.Sub(migrations, "migrations")
	if err != nil {
		panic(err) // the embedded directory always exists
	}
	return sub
}

// Migrate applies the service's migrations.
func Migrate(ctx context.Context, pool *pgxpool.Pool) ([]string, error) {
	return db.Migrate(ctx, pool, Migrations())
}

// ErrNotFound means the row does not exist (or is deleted).
var ErrNotFound = errors.New("store: not found")

// ErrNameTaken means a live resource already has the name.
var ErrNameTaken = errors.New("store: name taken")

// Store runs queries on a pool or in a transaction.
type Store struct {
	db sqlcdb.DBTX
	q  *sqlcdb.Queries
}

// New returns a Store over db (*pgxpool.Pool or pgx.Tx).
func New(db sqlcdb.DBTX) *Store { return &Store{db: db, q: sqlcdb.New(db)} }

func notFound(err error) error {
	if errors.Is(err, pgx.ErrNoRows) {
		return ErrNotFound
	}
	return err
}

// --- organizations ---

// InsertOrganization stores a new organization.
func (s *Store) InsertOrganization(ctx context.Context, o domain.Organization) error {
	labels, err := json.Marshal(o.Labels)
	if err != nil {
		return err
	}
	err = s.q.InsertOrganization(ctx, sqlcdb.InsertOrganizationParams{
		ID: o.ID, Name: o.Name, DisplayName: o.DisplayName, Description: o.Description, Labels: labels,
		OwnerUserID: o.OwnerUserID, BillingAccountID: o.BillingAccountID, Status: string(o.Status),
		IacTool: string(o.IacTool), Version: o.Version, CreatedAt: o.CreatedAt, UpdatedAt: o.UpdatedAt,
	})
	if db.IsUniqueViolation(err, "organizations_name") {
		return ErrNameTaken
	}
	return err
}

// GetOrganization returns a live organization; forUpdate locks the row.
func (s *Store) GetOrganization(ctx context.Context, id string, forUpdate bool) (domain.Organization, error) {
	get := s.q.GetOrganization
	if forUpdate {
		get = s.q.GetOrganizationForUpdate
	}
	row, err := get(ctx, id)
	if err != nil {
		return domain.Organization{}, notFound(err)
	}
	return organization(row)
}

// GetOrganizationByName returns the live organization with the name.
func (s *Store) GetOrganizationByName(ctx context.Context, name string) (domain.Organization, error) {
	row, err := s.q.GetOrganizationByName(ctx, name)
	if err != nil {
		return domain.Organization{}, notFound(err)
	}
	return organization(row)
}

// UpdateOrganization writes o if the stored version is prev.
func (s *Store) UpdateOrganization(ctx context.Context, o domain.Organization, prev int64) error {
	labels, err := json.Marshal(o.Labels)
	if err != nil {
		return err
	}
	n, err := s.q.UpdateOrganization(ctx, sqlcdb.UpdateOrganizationParams{
		ID: o.ID, DisplayName: o.DisplayName, Description: o.Description, Labels: labels,
		IacTool: string(o.IacTool), Version: o.Version, UpdatedAt: o.UpdatedAt, PrevVersion: prev,
	})
	return versioned(n, err)
}

func versioned(n int64, err error) error {
	if err != nil {
		return err
	}
	if n == 0 {
		return db.ErrConflict
	}
	return nil
}

func organization(r sqlcdb.Organization) (domain.Organization, error) {
	o := domain.Organization{
		ID: r.ID, Name: r.Name, DisplayName: r.DisplayName, Description: r.Description,
		OwnerUserID: r.OwnerUserID, BillingAccountID: r.BillingAccountID,
		Status: domain.OrganizationStatus(r.Status), IacTool: domain.IacTool(r.IacTool),
		Version: r.Version, CreatedAt: r.CreatedAt, UpdatedAt: r.UpdatedAt,
	}
	if err := json.Unmarshal(r.Labels, &o.Labels); err != nil {
		return domain.Organization{}, fmt.Errorf("organization %s: labels: %w", r.ID, err)
	}
	return o, nil
}

// --- projects ---

// InsertProject stores a new project.
func (s *Store) InsertProject(ctx context.Context, p domain.Project) error {
	labels, err := json.Marshal(p.Labels)
	if err != nil {
		return err
	}
	err = s.q.InsertProject(ctx, sqlcdb.InsertProjectParams{
		ID: p.ID, OrganizationID: p.OrganizationID, Name: p.Name, Description: p.Description, Labels: labels,
		Status: string(p.Status), Version: p.Version, CreatedAt: p.CreatedAt, UpdatedAt: p.UpdatedAt,
	})
	if db.IsUniqueViolation(err, "projects_name") {
		return ErrNameTaken
	}
	return err
}

// GetProject returns a live project; forUpdate locks the row.
func (s *Store) GetProject(ctx context.Context, id string, forUpdate bool) (domain.Project, error) {
	get := s.q.GetProject
	if forUpdate {
		get = s.q.GetProjectForUpdate
	}
	row, err := get(ctx, id)
	if err != nil {
		return domain.Project{}, notFound(err)
	}
	return project(row)
}

// UpdateProject writes p if the stored version is prev; a deleted project
// gets deleted_at and frees its name.
func (s *Store) UpdateProject(ctx context.Context, p domain.Project, prev int64) error {
	labels, err := json.Marshal(p.Labels)
	if err != nil {
		return err
	}
	var deletedAt *time.Time
	if p.Status == domain.ProjectDeleted {
		deletedAt = &p.UpdatedAt
	}
	n, err := s.q.UpdateProject(ctx, sqlcdb.UpdateProjectParams{
		ID: p.ID, Name: p.Name, Description: p.Description, Labels: labels, Status: string(p.Status),
		Version: p.Version, UpdatedAt: p.UpdatedAt, DeletedAt: deletedAt, PrevVersion: prev,
	})
	if db.IsUniqueViolation(err, "projects_name") {
		return ErrNameTaken
	}
	return versioned(n, err)
}

func project(r sqlcdb.Project) (domain.Project, error) {
	p := domain.Project{
		ID: r.ID, OrganizationID: r.OrganizationID, Name: r.Name, Description: r.Description,
		Status: domain.ProjectStatus(r.Status), Version: r.Version, CreatedAt: r.CreatedAt, UpdatedAt: r.UpdatedAt,
	}
	if err := json.Unmarshal(r.Labels, &p.Labels); err != nil {
		return domain.Project{}, fmt.Errorf("project %s: labels: %w", r.ID, err)
	}
	return p, nil
}

// --- access bindings ---

// Holder is a resource holding bindings.
type Holder struct {
	Type           string // domain.ResourceOrganization or domain.ResourceProject
	ID             string
	OrganizationID string
}

// ListBindings returns all bindings of a resource, ordered by ID.
func (s *Store) ListBindings(ctx context.Context, resourceID string) ([]domain.Binding, error) {
	rows, err := s.q.ListBindings(ctx, resourceID)
	if err != nil {
		return nil, err
	}
	return bindings(rows), nil
}

// ListBindingsPage returns up to limit bindings with IDs after afterID.
func (s *Store) ListBindingsPage(ctx context.Context, resourceID, afterID string, limit int) ([]domain.Binding, error) {
	rows, err := s.q.ListBindingsPage(ctx, sqlcdb.ListBindingsPageParams{
		ResourceID: resourceID, AfterID: afterID, Lim: int32(limit), //nolint:gosec // page sizes are ≤ 1001
	})
	if err != nil {
		return nil, err
	}
	return bindings(rows), nil
}

// ApplyBindings writes a binding change of h.
func (s *Store) ApplyBindings(ctx context.Context, h Holder, ch domain.BindingChange, now time.Time) error {
	for _, b := range ch.Removed {
		if err := s.q.DeleteBinding(ctx, b.ID); err != nil {
			return err
		}
	}
	for _, b := range ch.Added {
		if err := s.q.InsertBinding(ctx, sqlcdb.InsertBindingParams{
			ID: b.ID, ResourceType: h.Type, ResourceID: h.ID, OrganizationID: h.OrganizationID,
			RoleID: b.RoleID, SubjectType: string(b.Subject.Type), SubjectID: b.Subject.ID, CreatedAt: now,
		}); err != nil {
			return err
		}
	}
	return nil
}

// DeleteBindings removes all bindings of a resource.
func (s *Store) DeleteBindings(ctx context.Context, resourceID string) error {
	return s.q.DeleteResourceBindings(ctx, resourceID)
}

func bindings(rows []sqlcdb.AccessBinding) []domain.Binding {
	out := make([]domain.Binding, len(rows))
	for i, r := range rows {
		out[i] = domain.Binding{
			ID: r.ID, RoleID: r.RoleID,
			Subject: domain.Subject{Type: domain.SubjectType(r.SubjectType), ID: r.SubjectID},
		}
	}
	return out
}
